/**
 * Props of RoadmapGraph, generated by the content pipeline from the roadmap note itself (extract.ts):
 * headings become nodes, the bullets and table rows under them become items, and the lesson's
 * `nodeLinks` become links to lessons or to planned ("coming soon") modules.
 */
export interface RoadmapItem {
  /** progress key, the same one the page checklist uses for this item (see keys.ts) */
  key: string;
  text: string;
  /** table rows: the tag cell (🟢 MUST, 🟡 GOOD TO HAVE, ⚪ OPTIONAL) when the table has one */
  tag?: string;
  /** table rows: the remaining cells */
  detail?: string;
  /** true for table rows (only the graph shows checkboxes for them) */
  row?: boolean;
}

export interface RoadmapLink {
  title: string;
  /** site path under the base URL, e.g. "phase-2/pipeline/middleware/"; empty for planned modules */
  href: string;
  planned: boolean;
}

export interface RoadmapNode {
  id: string;
  title: string;
  depth: number;
  /** key used when the node has no items of its own: ticking the node stores this */
  key: string;
  items: RoadmapItem[];
  links: RoadmapLink[];
  children: RoadmapNode[];
}

export interface RoadmapData {
  /** full lesson id: progress is stored under it, shared with the page checklist */
  lessonId: string;
  title: string;
  nodes: RoadmapNode[];
}
